#!/usr/bin/env node
// Generate relations.d2 from the declarations themselves — datasets, their
// selections, and every combination wired to the selections it visits.
// Regenerated by render.sh, so the picture can never drift from the repo.
import { readdirSync, readFileSync, writeFileSync } from 'node:fs';
import { join, dirname } from 'node:path';
import { fileURLToPath } from 'node:url';

const repoRoot = join(dirname(fileURLToPath(import.meta.url)), '..', '..');
const load = (dir) =>
  readdirSync(join(repoRoot, dir))
    .filter((f) => f.endsWith('.json'))
    .map((f) => ({ name: f.replace(/\.json$/, ''), ...JSON.parse(readFileSync(join(repoRoot, dir, f), 'utf8')) }));

const datasets = load('datasets');
const combinations = load('combinations');

const countIds = (file) => {
  try {
    return readFileSync(join(repoRoot, file), 'utf8').split('\n').filter((l) => l.trim()).length;
  } catch {
    return '?';
  }
};

const d2 = ['vars: { d2-config: { theme-id: 200 } }', '', 'direction: right', '',
  'title: "What exists — datasets, selections, and the combinations that visit them" {',
  '  near: top-center; shape: text; style.font-size: 22; style.bold: true',
  '}', ''];

// Datasets as containers, selections as their children.
for (const ds of datasets) {
  d2.push(`${ds.name}: "DATASET ${ds.name}\\nmarker: ${ds.marker.type}" {`);
  d2.push('  style.fill: "#14352A"; style.stroke: "#2ECC71"; style.font-color: "#E8F8F0"');
  for (const [sel, decl] of Object.entries(ds.selections)) {
    const n = countIds(decl.file);
    const how = decl.rule ? (decl.rule.n ? `seeded ${decl.rule.n}` : 'rule: all') : 'hand-frozen';
    d2.push(`  ${sel}: "${sel} — ${n} instances\\n(${how})"`);
  }
  d2.push('}', '');
}

// Combinations as nodes; an edge to each selection they visit.
for (const combo of combinations) {
  const models = combo.legs.map((l) => l.model.split('/').pop().replace(/^claude-/, ''));
  const knobs = [];
  if (combo.configs) knobs.push('VARIATION: own prompt/timeout configs');
  const efforts = [...new Set(combo.legs.map((l) => l.effort).filter(Boolean))];
  if (efforts.length > 0) knobs.push(`efforts: ${efforts.join(', ')}`);
  const modelLine = models.length > 4 ? `${models.length} models` : models.join(', ');
  const knobLine = knobs.length > 0 ? `\\n${knobs.join('; ')}` : '';
  const style = combo.configs
    ? 'style.fill: "#3A1714"; style.stroke: "#E74C3C"; style.font-color: "#FBEAEA"; style.stroke-dash: 3'
    : 'style.fill: "#2E1E0E"; style.stroke: "#E67E22"; style.font-color: "#FBEFE3"';
  d2.push(`combo_${combo.name.replaceAll('-', '_')}: "combination ${combo.name}\\n${modelLine}${knobLine}\\n→ runs/${combo.legs[0].out.split('/')[1]}/" { ${style} }`);
  for (const sel of combo.selections) {
    d2.push(`combo_${combo.name.replaceAll('-', '_')} -> ${combo.dataset}.${sel}: "visits"`);
  }
  d2.push('');
}

d2.push('note: "Green containers are datasets with their frozen selections. Orange boxes are combinations (solid = control knobs); red dashed are variations — same selection, different prompt/timeout. Generated from datasets/*.json and combinations/*.json by generate-relations.mjs." {');
d2.push('  near: bottom-center; shape: text; style.font-color: "#7F8C8D"');
d2.push('}');

const out = join(repoRoot, 'docs', 'diagrams', 'relations.d2');
writeFileSync(out, d2.join('\n') + '\n');
console.log(`wrote ${out}`);
